  await l.f.schedule(third.request.original,{usage:'manual'});assert.equal(result<{status:string}>(await l.call(restarted,{kind:'dispatch',original:third.request.original})).status,'accepted');await l.f.finalize(third.request.original);assert.equal(result<{status:string}>(await l.call(restarted,{kind:'reconcile',original:third.request.original})).status,'settled');
  const frozen=await l.snapshot(),counts=await l.f.counters();for(const requester of ['engine','adapter'] as const)assert.equal((await l.call(restarted,{kind:'retry',retry:l.retry(input.request,third.request.original,requester)}))['error'],'UNKNOWN_EFFECT_REQUIRES_RECONCILIATION');assert.deepEqual(await l.snapshot(),frozen);await l.unchangedAccept(counts);
