   result(await n.call(next,'qualify',{}));const thirdCommand={...await n.command(a.sessionId),operationId:o.operationId,input:'success',choice:null};assert.equal(result<{status:string}>(await n.call(next,'retryTurn',thirdCommand)).status,'completed');const third=await latest(3);const frozen=await n.snapshot(),counts=await f.counters();assert.ok((await n.call(next,'retryTurn',{...await n.command(a.sessionId),operationId:o.operationId,input:'fourth',choice:null}))['error']);assert.equal((await n.call(next,'retryTurn',{...thirdCommand,retryCeiling:3}))['error'],'INVALID_SCHEMA');assert.deepEqual(await n.snapshot(),frozen);for(const key of ['accept','acceptance'])assert.equal((await f.counters())[key],counts[key]);assert.equal((await f.journal(third)).receipt.outcome,'answer');assert.equal((await f.journal(second)).receipt.outcome,'known-failure');assert.equal((await f.admin.query('SELECT record FROM fabric.model_operations WHERE operation_id=$1',[o.operationId])).rows[0].record.attemptsTaken,3);await stopOwned(next);
