  if(proof.status==='committed'){assert.equal((await l.call(next,{kind:'lookup',key:input.command.key,digest:hash('changed digest')}))['error'],'IDEMPOTENCY_CONFLICT');const other=await l.caller(0);assert.equal(result<{status:string}>(await l.call(other,{kind:'lookup',key:input.command.key,digest})).status,'absent-safe');await stopOwned(other);const cross=await l.caller(1,l.f.otherSpace);assert.equal(result<{status:string}>(await l.call(cross,{kind:'lookup',key:input.command.key,digest})).status,'absent-safe');await stopOwned(cross);}
