  const a=await l.task(),input=await a.makeInput(),o=input.request.original,p=await l.caller(),reader=await l.caller();result(await l.call(p,{kind:'prepare',input}));await l.f.schedule(o,{usage:'manual'},crash);await l.f.arm('owner-commit');const before=await l.f.counters(),dispatch=await l.start(p,{kind:'dispatch',original:o});await l.f.reached('owner-commit',o);assert.equal(await l.f.journal(o),undefined);assert.equal((await l.reservation(o)).state,'active');assert.equal(await l.count('model_claims',o),1);
  const pending=await l.start(reader,{kind:'reconcile',original:o});await l.blocked(pending);assert.equal(reader.messages.some(m=>m['requestId']===pending.requestId&&m['kind']==='result'),false);assert.equal(await l.count('model_resolutions',o),0);await l.unchangedAccept(before);
